func New(opts ...fx.Option) App {
	return App{
		fx.New(
			fx.Options(opts...),
			fx.Provide(
				newBinderConfig,
				newConfig,
				newFilterApiConfig,
				newOptimizationFacadeConfig,
				newPrinsConfig,
				newHttpClient,
				filterservice.NewClient,
				optimizationfacade.NewClient,
				optimizationfacade.NewComponentProvider,
				optimizationfacade.NewConfigurationGenerator,
				optimizationfacade.NewStartConfigurationProvider,
				prins.NewClient,
				prins.NewConfigurationFetcher,
				service.NewRulesetValidator,
				fx.Annotate(
					func(cfg config, client *http.Client) *graphql.Client {
						return graphql.NewClient(
							cfg.PrinsBaseUrl,
							graphql.WithHTTPClient(client),
						)
					},
					fx.As(new(prins.MachineboxClient)),
				),
			),
			fx.Invoke(runValidation),
		),
	}
}

