func setEnvVariables(binder *binder.Config) {
	syncEnvs := []string{
		"LOG_LEVEL",
	}

	// sync binder values with env before InitTracing is called
	for _, e := range syncEnvs {
		if v, ok := binder.Values().Get(e); ok {
			_ = os.Setenv(e, v)
		}
	}
}

