func ParsePno34(s string, wheelCodes []string, week int) (CarConfiguration, error) {
	r := regexp.MustCompile(pno34Regex)
	groups := getGroups(r, s)

	pno12, err := pno12FromGroups(groups)
	if err != nil {
		return CarConfiguration{}, err
	}

	var options []string
	var wheel string

	for k, entry := range groups {
		if k == OPTION {
			items := splitItemsFromGroupEntry(entry)
			for _, item := range items {
				if contains(wheelCodes, item) {
					if wheel != "" {
						return CarConfiguration{}, errors.Errorf("two wheels in configuration %s and %s for %s", wheel, item, s)
					}
					wheel = item
					continue
				}
				options = append(options, item)
			}
		}
		if k == FEATURE && entry != "" {
			if wheel != "" {
				return CarConfiguration{}, errors.Errorf("two wheels in configuration %s and %s for %s", wheel, entry, s)
			}
			wheel = entry
		}
	}

	if wheel == "" {
		return CarConfiguration{}, errors.Errorf("no wheel in configuration for %s", s)
	}

	if groups[MODEL_YEAR] == "" {
		return CarConfiguration{}, errors.Errorf("no model year in configuration for %s", s)
	}
	modelYear, err := strconv.Atoi(groups[MODEL_YEAR])
	if err != nil {
		return CarConfiguration{}, errors.Errorf("model year in configuration could not be converted to integer %s", s)
	}

	// Disregard packages and s message
	return CarConfiguration{
		SpecMarket: groups[SPEC_MARKET],
		ModelYear:  modelYear,
		Pno34: Pno34{
			Pno12:    pno12,
			Color:    groups[COLOR],
			Interior: groups[UPHOLSTERY],
			Wheel:    wheel,
			Options:  options,
		},
		ProductionWeek: week,
	}, nil
}

