func ExtractComponentsToVary(
	prinsConfigurations []PrinsConfiguration,
	wheelCodes []string,
	standardWheelByPno12 map[Pno12]string,
) []ComponentsToVary {
	componentsToVaryMap := make(map[Pno12]*ComponentsToVary)

	groupedPrinsConfigurations := groupPrinsConfigurationsByPno12(prinsConfigurations)

	for pno12, pcs := range groupedPrinsConfigurations {
		if _, ok := componentsToVaryMap[pno12]; !ok {
			componentsToVaryMap[pno12] = &ComponentsToVary{
				Pno12: pno12,
			}
		}

		if prinsConfigurationsWithoutWheelCodeExist(pcs, wheelCodes) {
			standardWheelCode, ok := standardWheelByPno12[pno12]
			if ok {
				componentsToVaryMap[pno12].addWheel(standardWheelCode)
			}
		}

		for _, pc := range pcs {

			componentsToVaryMap[pno12].addColor(pc.Color)
			componentsToVaryMap[pno12].addInterior(pc.Interior)

			for _, option := range pc.Options {
				if contains(wheelCodes, option) {
					componentsToVaryMap[pno12].addWheel(option)
					continue
				}
				componentsToVaryMap[pno12].addOption(option)
			}
		}
	}

	var componentsToVary []ComponentsToVary
	for _, c := range componentsToVaryMap {
		componentsToVary = append(componentsToVary, *c)
	}

	return componentsToVary
}

