func ParsePrinsPno(s string) (PrinsConfiguration, error) {
	r := regexp.MustCompile(pnoPrinsRegex)
	groups := getGroups(r, s)

	var options []string
	for k, group := range groups {
		if k == OPTION {
			for _, option := range strings.Split(group, " ") {
				if option != "" {
					options = append(options, option)
				}
			}
		}
	}

	pno12, err := pno12FromGroups(groups)
	if err != nil {
		return PrinsConfiguration{}, err
	}

	return PrinsConfiguration{
		Pno12:    pno12,
		Color:    groups[COLOR],
		Interior: groups[UPHOLSTERY],
		Options:  options,
	}, nil
}

