	if len(response.Components) == 0 {
		return "", errors.Errorf("no components found for pno12 %s", pno12)
	}

	var components []domain.Component
	for _, component := range response.Components {
		components = append(components, domain.Component{
			Type: component.Type,
			Code: component.Name,
		})
	}

	standardWheelCode, found := domain.FindStandardWheel(components)
	if !found {
		return "", nil
	}

	return standardWheelCode, nil
}

