func (rv *RulesetValidator) validatePrinsConfigurationsPermittedByCCE(
	ctx context.Context,
	specMarket string,
	policyID string,
	modelYear int,
	manyComponentsToVary []domain.ComponentsToVary,
	startConfigurations []domain.CarConfiguration,
	prinsConfigurations domain.PrinsConfigurations,
	wheelCodes []string,
) error {
	success := true
	fmt.Println("Validating that CCE allows all configurations that are allowed by PRINS storedCpvSets")
	bar := progressbar.Default(int64(len(prinsConfigurations)))
	for _, prinsConfiguration := range prinsConfigurations {
		bar.Add(1)
		startConfiguration, found := getStartConfiguration(startConfigurations, modelYear, specMarket, prinsConfiguration.Pno12)
		if !found {
			fmt.Printf("could not find start configuration for pno12 %s\n", prinsConfiguration.Pno12.String())
			success = false
			continue
		}

		componentsToVary, found := getComponentsToVary(startConfiguration.Pno34.Pno12, manyComponentsToVary)
		if !found {
			fmt.Printf("could not find components to vary for pno12 %s\n", startConfiguration.Pno34.Pno12.String())
			success = false
			continue
		}

		carConfiguration, err := rv.configurationGenerator.GenerateFromPrinsConfiguration(
			ctx,
			specMarket,
			policyID,
			modelYear,
			startConfiguration.ProductionWeek,
			wheelCodes,
			prinsConfiguration,
		)
		if err != nil {
			return err
		}

		if !prinsConfiguration.Matches(carConfiguration, componentsToVary) {
			fmt.Printf("WARNING! PRINS configuration %s does not match car configuration %+v\n", prinsConfiguration, carConfiguration)
			success = false
		}
	}

	if !success {
		return errors.New("WARNING! Not all configurations were matched")
	}
	return nil
}

