`query StoredCpvSetsQuery(
	$offset: Int!,
	$limit: Int!,
	$configDictionaryName: String!,
	$specMarket: String,
	$modelYear: String
) {
	storedCpvSets(
		where: {
			configurationDictionary: {
				name: $configDictionaryName
			}
			NOT:{status:"Obsolete"}
			specMarkets_SOME: { name: $specMarket }
			modelYear_STARTS_WITH: $modelYear
		},
		options: {
			limit: $limit,
			offset: $offset,
		}
	)

	{
		status
		modelYear
		pno
		effectiveInWeek
		effectiveOutWeek
	}
}
`

